const sd = $getWorkflowStaticData('global');
const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;

// Keep the covered-topic ledger, prune anything older than 7 days (migrates the old string format too)
sd.usedTopics = (sd.usedTopics || [])
  .map(t => typeof t === 'string' ? { title: t, ts: now } : t)
  .filter(t => t && t.title && (now - (t.ts || 0)) < SEVEN_DAYS)
  .slice(-60);

// Fresh per-run state
sd.candidatePool = [];
sd.currentBatch = null;

// Drop leftovers from the old approval-loop version of this workflow
delete sd.rejectedLinks;
delete sd.currentSelection;
delete sd.attemptCount;
delete sd.candidates;
delete sd.runCount;

return $input.all();

const sd = $getWorkflowStaticData('global');
const now = Date.now();
const TOPICS_PER_RUN = 3;

const usedTitles = new Set((sd.usedTopics || []).map(t => String(t.title || '').toLowerCase().trim()));

const all = $input.all()
  .map(i => i.json)
  .filter(a => a && a.title && a.link && a.isoDate);

function collect(hours) {
  const cutoff = now - hours * 60 * 60 * 1000;
  const seenTitles = new Set();
  const seenLinks = new Set();
  const out = [];
  for (const a of all) {
    const ts = new Date(a.isoDate).getTime();
    if (isNaN(ts) || ts < cutoff) continue;
    const titleKey = String(a.title).toLowerCase().trim();
    if (seenTitles.has(titleKey) || seenLinks.has(a.link)) continue;
    seenTitles.add(titleKey);
    seenLinks.add(a.link);
    if (usedTitles.has(titleKey)) continue;
    out.push({
      title: String(a.title).trim(),
      link: a.link,
      snippet: String(a.contentSnippet || '').slice(0, 300),
      isoDate: a.isoDate,
    });
  }
  return out;
}

// Widen the window until there is enough material for three separate topics
let windowHours = 6;
let candidates = [];
for (const h of [6, 12, 24, 48]) {
  windowHours = h;
  candidates = collect(h);
  if (candidates.length >= TOPICS_PER_RUN) break;
}

sd.candidatePool = candidates;

return [{ json: {
  found: candidates.length > 0,
  topicsPerRun: TOPICS_PER_RUN,
  windowHours: windowHours,
  candidateCount: candidates.length,
  candidates: candidates,
  usedTopics: (sd.usedTopics || []).map(t => t.title),
  reason: candidates.length
    ? ''
    : 'No publishable articles were found. The window was widened from 6 to 48 hours and the feeds still returned nothing that was not already covered.',
} }];

