const WANTED = 3;

let pool = [];
try { pool = $('Shortlist Builder').first().json.candidates || []; } catch (e) {}
if (!pool.length) {
  const sdPool = $getWorkflowStaticData('global').candidatePool;
  pool = Array.isArray(sdPool) ? sdPool : [];
}
if (!pool.length) {
  throw new Error('Trio Resolver received no candidate pool. Unpin Shortlist Builder and run the full flow.');
}

const out = ($input.first().json.output) || {};
let picked = out.articles;
if (!Array.isArray(picked)) picked = picked ? [picked] : [];

const byLink = new Map(pool.map(c => [c.link, c]));
const byTitle = new Map(pool.map(c => [String(c.title).toLowerCase().trim(), c]));

const chosen = [];
const taken = new Set();

for (const p of picked) {
  if (!p) continue;
  const match = byLink.get(p.link) || byTitle.get(String(p.title || '').toLowerCase().trim());
  if (!match || taken.has(match.link)) continue;
  taken.add(match.link);
  chosen.push({ ...match, reason: String(p.reason || '').trim() });
  if (chosen.length === WANTED) break;
}

// Top up with the freshest untouched candidates if the model returned fewer than three usable picks
if (chosen.length < WANTED) {
  const filler = pool
    .filter(c => c && c.link && !taken.has(c.link))
    .sort((a, b) => new Date(b.isoDate) - new Date(a.isoDate));
  for (const c of filler) {
    taken.add(c.link);
    chosen.push({ ...c, reason: 'Auto-filled because the model returned fewer usable picks than requested.' });
    if (chosen.length === WANTED) break;
  }
}

if (!chosen.length) {
  throw new Error('Trio Resolver could not resolve a single article from the candidate pool.');
}

const sd = $getWorkflowStaticData('global');
sd.currentBatch = chosen.map(c => ({ title: c.title, link: c.link }));

return chosen.map((c, i) => ({ json: {
  slot: i + 1,
  title: c.title,
  link: c.link,
  isoDate: c.isoDate,
  pickReason: c.reason,
} }));

const MIN_CHARS = 200;

const picks = $('Trio Resolver').all().map(i => i.json);
const fetched = $input.all().map(i => i.json || {});

function textOf(j) {
  if (!j) return '';
  if (typeof j.content === 'string') return j.content;
  if (j.data && typeof j.data.content === 'string') return j.data.content;
  if (typeof j.data === 'string') return j.data;
  if (typeof j.text === 'string') return j.text;
  return '';
}

function urlOf(j) {
  if (!j) return '';
  return String(j.url || (j.data && j.data.url) || '');
}

const out = [];
const skipped = [];

picks.forEach((p, idx) => {
  // Prefer matching by URL, fall back to positional pairing
  let src = fetched.find(f => urlOf(f) && urlOf(f) === p.link);
  if (!src) src = fetched[idx];

  const content = textOf(src).trim();
  if (content.length < MIN_CHARS) {
    skipped.push(p.title);
    return;
  }

  let publication = '';
  const m = String(p.link || '').match(/^https?:\/\/(?:www\.)?([^\/]+)/i);
  if (m) publication = m[1];

  out.push({ json: {
    slot: p.slot,
    title: p.title,
    link: p.link,
    pickReason: p.pickReason || '',
    publication: publication,
    content: content.slice(0, 20000),
    contentLength: content.length,
  } });
});

if (!out.length) {
  throw new Error('None of the selected articles returned enough readable text. Skipped: ' + skipped.join(' | '));
}

return out;

