const sources = $('Source Text Normalizer').all().map(i => i.json);
const drafts = $input.all().map(i => i.json || {});

const TLD = '(?:com|net|org|io|ai|co|dev|app|news|tech|info|biz|me|xyz|us|uk|eu|de|fr|nl|es|it|ca|au|in|jp)';

// Safety net: the prompt forbids links, this guarantees none survive into the post.
// LinkedIn auto-links bare domains, so those go too, not just full URLs.
function stripLinks(text) {
  let s = String(text || '');

  s = s.replace(/\bhttps?:\/\/\S+/gi, '');
  s = s.replace(/\bwww\.[^\s)\]]+/gi, '');
  s = s.replace(new RegExp('\\b[a-z0-9][a-z0-9-]*(?:\\.[a-z0-9-]+)*\\.' + TLD + '\\b(?:\\/[^\\s)\\]]*)?', 'gi'), '');

  // Tidy up whatever the removals left behind
  s = s.replace(/\((?:\s*via\s*)?\s*\)/gi, '');
  s = s.replace(/[ \t]{2,}/g, ' ');
  s = s.replace(/[ \t]+([.,;:!?])/g, '$1');
  s = s.replace(/\n{3,}/g, '\n\n');

  return s.trim();
}

const out = [];
const dropped = [];

// One failed or empty draft must not take the rest of the batch down with it
drafts.forEach((d, i) => {
  const src = sources[i] || {};
  const res = d.output || {};
  const post = stripLinks(res.post);

  if (d.error || !post) {
    dropped.push(src.title || ('slot ' + (i + 1)));
    return;
  }

  out.push({ json: {
    slot: src.slot || (i + 1),
    headline: String(res.headline || src.title || '').trim(),
    post: post,
    postLength: post.length,
    imageQuery: String(res.image_query || '').trim() || 'business technology',
    title: src.title || '',
    link: src.link || '',
    publication: src.publication || '',
    pickReason: src.pickReason || '',
  } });
});

if (!out.length) {
  throw new Error('Copy Composer produced no usable posts. Dropped: ' + dropped.join(' | '));
}

return out;

// LinkedIn single-image post: 1200 x 627 px, 1.91:1. Same ratio LinkedIn uses for the feed card.
const LI_WIDTH = 1200;
const LI_HEIGHT = 627;
const QUALITY = 80;

const drafts = $('Draft Packager').all().map(i => i.json);
const responses = $input.all().map(i => i.json || {});

function linkedInCrop(rawUrl, w, h, q) {
  const sep = rawUrl.includes('?') ? '&' : '?';
  return rawUrl + sep
    + 'fm=jpg&cs=srgb&auto=compress&fit=crop&crop=faces,entropy'
    + '&w=' + w + '&h=' + h + '&q=' + q;
}

const usedIds = new Set();

return drafts.map((d, i) => {
  const res = responses[i] || {};
  const results = Array.isArray(res.results) ? res.results : [];

  // Wide enough to crop to 1200x627 without upscaling, landscape, and not already used by another topic in this run
  const clean = results.filter(p =>
    p && p.id && p.urls && p.urls.raw && !usedIds.has(p.id)
  );
  const ideal = clean.filter(p =>
    (p.width || 0) >= LI_WIDTH &&
    (p.height || 0) >= LI_HEIGHT &&
    (p.width || 0) >= (p.height || 0)
  );

  const photo = ideal[0] || clean[0] || null;

  if (!photo) {
    return { json: {
      ...d,
      hasVisual: false,
      visualId: '',
      visualUrl: '',
      visualPreviewUrl: '',
      visualAlt: '',
      visualSpec: LI_WIDTH + 'x' + LI_HEIGHT,
      visualCredit: '',
      visualCreditUrl: '',
      downloadLocation: '',
    } };
  }

  usedIds.add(photo.id);

  const author = (photo.user && photo.user.name) || 'Unsplash';
  const authorUrl = (photo.user && photo.user.links && photo.user.links.html) || 'https://unsplash.com';
  const utm = '?utm_source=n8n_clickup_bot&utm_medium=referral';

  return { json: {
    ...d,
    hasVisual: true,
    visualId: photo.id,
    visualUrl: linkedInCrop(photo.urls.raw, LI_WIDTH, LI_HEIGHT, QUALITY),
    visualPreviewUrl: linkedInCrop(photo.urls.raw, 600, Math.round(600 * LI_HEIGHT / LI_WIDTH), 70),
    visualAlt: photo.alt_description || '',
    visualSpec: LI_WIDTH + 'x' + LI_HEIGHT + ' px, 1.91:1, LinkedIn single-image post',
    visualCredit: 'Photo by ' + author + ' on Unsplash',
    visualCreditUrl: authorUrl + utm,
    downloadLocation: (photo.links && photo.links.download_location) || '',
  } };
});

const topics = $('Hero Visual Selector').all().map(i => i.json);

return topics.map((t, i) => {
  const lines = [];

  lines.push('**POST ' + (i + 1) + ' SUGGESTION**');
  lines.push('');
  lines.push('**' + String(t.headline || '').trim() + '**');
  lines.push('');
  lines.push(t.post);
  lines.push('');
  lines.push('----');
  lines.push('');
  // Direct 1200x627 JPG, right-click and save straight from the browser
  lines.push('Link to image: ' + (t.hasVisual ? t.visualUrl : 'no match for "' + t.imageQuery + '"'));
  lines.push('Source: ' + t.link);

  return { json: {
    slot: t.slot,
    headline: t.headline,
    title: t.title,
    link: t.link,
    visualUrl: t.visualUrl || '',
    messageMarkdown: lines.join('\n'),
  } };
});

const sd = $getWorkflowStaticData('global');
const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;

const batch = $('Hero Visual Selector').all().map(i => i.json);
const dispatch = $input.all().map(i => i.json || {});

let usedTopics = (sd.usedTopics || [])
  .map(t => typeof t === 'string' ? { title: t, ts: now } : t)
  .filter(t => t && t.title && (now - (t.ts || 0)) < SEVEN_DAYS);

const sent = [];
const failed = [];

// Only mark a topic as covered once ClickUp actually accepted it, so a failed
// send comes back around on the next run instead of being silently burned
batch.forEach((b, i) => {
  if (!b || !b.title) return;
  const res = dispatch[i];
  if (res && !res.error) {
    usedTopics.push({ title: b.title, ts: now });
    sent.push(b);
  } else {
    failed.push(b.title);
  }
});

sd.usedTopics = usedTopics.slice(-60);
sd.candidatePool = [];
sd.currentBatch = null;

return [{ json: {
  deliveredTopics: sent.length,
  failedTopics: failed,
  withVisual: sent.filter(b => b.hasVisual).length,
  topics: sent.map(b => ({
    headline: b.headline,
    title: b.title,
    link: b.link,
    visualUrl: b.visualUrl || null,
  })),
} }];
